\title{The Exact Value of the Binomial GCD A080170:\\
A Disproof of Stephan's Conjecture and a Carry-Minimum Correction}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
For an integer $k \ge 2$ define the \emph{binomial gcd}
\[
D(k) \;=\; \gcd_{2 \le q \le k+1} \bin{qk}{k},
\]
the integer sequence catalogued as OEIS \textbf{A080170}. Let
$P(n) = \max_{p \mid n} p^{\val_p(n)}$ denote the \emph{dominant prime power}
of $n$, where $\val_p$ is the $p$-adic valuation. Ralf Stephan's conjecture
(entry 17 in his list of conjectures on integer sequences) proposes an exact
closed form: $D(k) = P(k+1)$ whenever $\frac{k+1}{P(k+1)} \le P(k+1)$, and
$D(k) = 1$ otherwise.

We prove that the \textbf{exact-value} part of this conjecture is
\textbf{false}. The first counterexample is $k = 11$: with $n = 12 = 2^2\cdot 3$
the formula predicts $P(12) = 4$, but in fact $D(11) = 2$. The disproof is
structural rather than computational: the gcd divides the term $\bin{55}{11}$,
and a single base-$2$ carry shows $4 \nmid \bin{55}{11}$. Conversely, we prove
the conjecture is \textbf{exact on the prime fibre}: for every prime $p$ we have
$p \mid D(p-1)$ and $p^2 \nmid D(p-1)$, so the exact power of $p$ dividing
$D(p-1)$ is $p^1$. Both directions follow from \textbf{Kummer's theorem}, which
identifies $\val_p(\bin{qk}{k})$ with the number of base-$p$ carries when adding
$k$ and $(q-1)k$. We further record three conjectures that survived exhaustive
testing for $2 \le k \le 201$ and discuss their proof strategies.
\end{abstract}

\section{Introduction}

Divisibility properties of binomial coefficients form one of the oldest and most
productive corners of number theory. Classical results---Kummer's carry theorem
(1852), Lucas' congruence, and the gcd identities of a Pascal row---repeatedly
show that the arithmetic of $\bin{a}{b}$ is governed by digit-level
combinatorics in a prime base.

The sequence A080170 packages a particularly attractive instance:
\[
D(k) = \gcd_{2 \le q \le k+1} \bin{qk}{k}, \qquad k \ge 2.
\]
The first values are
\[
D(2),D(3),\dots = 3,\,4,\,5,\,3,\,7,\,8,\,9,\,5,\,11,\,2,\,13,\,7,\,5,\,16,\,17,\,9,\,19,\dots
\]
Numerically these track the dominant prime power of $k+1$ at the start, which led
Ralf Stephan to conjecture an exact closed form. This paper settles the
exact-value claim (false), proves the part that is true (the prime fibre), and
extracts the correct governing law from the failure.

Our contributions are: (1) a formally verified disproof of the exact-value
conjecture, first counterexample $k = 11$, via divisibility rather than
enumeration (Theorem~\ref{thm:disproof}); (2) formally verified exactness on the
prime fibre, $p \mid D(p-1)$ and $p^2 \nmid D(p-1)$ for every prime $p$
(Theorems~\ref{thm:pdvd} and \ref{thm:psq}); (3) a Kummer-based diagnosis of why
the conjecture fails in general but succeeds on prime powers, with a corrected
carry-minimum formula (Section~\ref{sec:corrected}).

\section{Definitions and preliminaries}

Throughout, $p$ is prime, $\val_p(n)$ is the $p$-adic valuation, and we write
$p^a \,\|\, n$ for $a = \val_p(n)$.

\begin{definition}[Binomial gcd, A080170]
For $k \ge 2$, $\displaystyle D(k) = \gcd_{2 \le q \le k+1} \bin{qk}{k}$.
\end{definition}

\begin{definition}[Dominant prime power]
For $n \ge 1$, $\displaystyle P(n) = \max_{p \mid n} p^{\val_p(n)}$, the largest
exact prime-power component of $n$. E.g. $P(12) = \max(2^2,3^1) = 4$ and
$P(360) = \max(2^3,3^2,5^1) = 9$.
\end{definition}

\begin{conjecture}[Stephan, entry 17]
For all $k \ge 2$, with $n = k+1$: if $n/P(n) \le P(n)$ then $D(k) = P(n)$, else
$D(k) = 1$. Equivalently $D(k) > 1 \iff n/P(n) \le P(n)$.
\end{conjecture}

\begin{lemma}[gcd divides each term]\label{lem:gcddvd}
For every $q$ with $2 \le q \le k+1$, $D(k) \mid \bin{qk}{k}$.
\end{lemma}
\begin{proof}
Immediate from the definition of gcd over a finite family.
\end{proof}

\begin{theorem}[Kummer, 1852]\label{thm:kummer}
For a prime $p$ and nonnegative integers $a,b$, $\val_p(\bin{a+b}{a})$ equals the
number of carries when adding $a$ and $b$ in base $p$.
\end{theorem}

Applied with $N = qk$, $r = k$, $N - r = (q-1)k$:
\begin{equation}
\val_p\!\left(\bin{qk}{k}\right) = \#\{\text{carries adding } k \text{ and } (q-1)k \text{ in base } p\}.
\label{eq:kummer}
\end{equation}
Since the gcd contains the minimum power of each prime across the family,
\begin{equation}
\val_p(D(k)) = \min_{2 \le q \le k+1} \val_p\!\left(\bin{qk}{k}\right).
\label{eq:min}
\end{equation}

\section{The prime fibre: the conjecture is exactly right}

Set $k = p-1$, so $qk = q(p-1)$ and the central term is $q = 2$.

\begin{lemma}[single-carry lower bound]\label{lem:lb}
Let $p$ be prime and $2 \le q \le p$. Then $p \mid \bin{q(p-1)}{p-1}$.
\end{lemma}
\begin{proof}
By \eqref{eq:kummer} it suffices to find one carry adding $p-1$ and $(q-1)(p-1)$
in base $p$. The units digit of $p-1$ is $p-1$, and that of $(q-1)(p-1)$ is
$p-(q-1)$ for $2 \le q \le p$; their sum is $2p - q \ge p$, producing a carry.
Hence $\val_p(\bin{q(p-1)}{p-1}) \ge 1$.
\end{proof}

\begin{theorem}[prime divides the gcd]\label{thm:pdvd}
For every prime $p$, $p \mid D(p-1)$.
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:lb}, $p$ divides every term $\bin{q(p-1)}{p-1}$ for
$2 \le q \le p = (p-1)+1$, hence $p$ divides their gcd.
\end{proof}

\begin{lemma}[central valuation is one]\label{lem:central}
For every prime $p$, $\val_p(\bin{2(p-1)}{p-1}) = 1$; equivalently
$p^2 \nmid \bin{2(p-1)}{p-1}$.
\end{lemma}
\begin{proof}
Add $p-1$ to itself in base $p$: the units digits sum to $2p-2 = 1\cdot p+(p-2)$,
one carry; all higher digits are zero and the carried $1$ produces none. So
exactly one carry, and by Theorem~\ref{thm:kummer} the valuation is $1$.
\end{proof}

\begin{theorem}[$p^2$ does not divide the gcd]\label{thm:psq}
For every prime $p$, $p^2 \nmid D(p-1)$.
\end{theorem}
\begin{proof}
The index $q = 2$ lies in $[2,(p-1)+1]$, so by Lemma~\ref{lem:gcddvd}
$D(p-1) \mid \bin{2(p-1)}{p-1}$. If $p^2 \mid D(p-1)$ then
$p^2 \mid \bin{2(p-1)}{p-1}$, contradicting Lemma~\ref{lem:central}.
\end{proof}

\begin{corollary}[exact $p$-part]
For every prime $p$, $\val_p(D(p-1)) = 1$; with the computational fact that
$D(p-1)$ has no other prime factor, $D(p-1) = p$, matching Stephan exactly.
\end{corollary}

\section{The general exact-value conjecture is false}

\begin{theorem}[disproof of the exact value]\label{thm:disproof}
It is not the case that $D(k) = P(k+1)$ for all $k \ge 2$. Explicitly,
$D(11) = 2$ while $P(12) = 4$.
\end{theorem}
\begin{proof}
Suppose $D(k) = P(k+1)$ for all $k \ge 2$. For $k = 11$, $12 = 2^2\cdot 3$ gives
$P(12) = 4$, so $D(11) = 4$. The index $q = 5$ satisfies $2 \le 5 \le 12$, so by
Lemma~\ref{lem:gcddvd},
\[
D(11) \mid \bin{55}{11} = 119{,}653{,}565{,}850,
\]
whence $4 \mid \bin{55}{11}$. But $\bin{55}{11} \equiv 2 \pmod 4$, a
contradiction. Hence $D(11) \ne 4$.
\end{proof}

\begin{remark}[carry explanation]
Take $p = 2$, $k = 11 = 1011_2$. For $q = 5$, adding $11$ and $44 = 101100_2$ in
base $2$ produces exactly one carry, so $\val_2(\bin{55}{11}) = 1$. By
\eqref{eq:min}, $\val_2(D(11)) \le 1$, so the $2$-part is at most $2^1$.
Stephan's formula assumed the dominant $2^2$ survives; a single low-carry term
$q$ destroys the top digit. Prime powers, lacking a complementary factor, are
immune.
\end{remark}

\begin{remark}[failure set]
The formula also fails at $k = 23,29,35,39,44,47,55,59,62,69,71,79,\dots$---
exactly those $k$ whose $n = k+1$ has $m = n/p^a > 1$ for the dominant prime.
\end{remark}

\section{The corrected law and surviving conjectures}\label{sec:corrected}

For a prime $p$ with $p^a \,\|\, n$ and $m = n/p^a$, the minimum carry count is
$a$ reduced by the top digits cancelled against $m$, namely $\lfloor\log_p m\rfloor$.

\begin{conjecture}[corrected closed form]
For all $k \ge 2$, with $n = k+1$,
\[
D(k) = \max_{p \mid n} p^{\max(0,\,\val_p(n) - \lfloor \log_p(n/p^{\val_p(n)})\rfloor)},
\]
($=1$ if all exponents vanish). It matches $D(k)$ for all $2 \le k \le 201$, and
reduces to $P(n)$ when $n$ is a prime power ($m=1$). At $k=11$: $p=2$, $a=2$,
$m=3$, $\lfloor\log_2 3\rfloor=1$, exponent $1$, $D(11)=2$.
\end{conjecture}

\begin{conjecture}[sharp nontriviality]
For all $k \ge 2$, $D(k) > 1 \iff (k+1)/P(k+1) \le P(k+1)$. Survived all testing
to $k = 201$.
\end{conjecture}

\begin{conjecture}[prime-power valued]
For all $k \ge 2$, $D(k) \in \{1\}\cup\{p^b : p \text{ prime}\}$. Verified for
$2 \le k \le 201$; at most one prime can contribute, by a two-prime
incompatibility of minimal-carry witnesses.
\end{conjecture}

\begin{conjecture}[full prime-power fibre]
For every prime $p$ and $a \ge 1$, $D(p^a - 1) = p^a$. The central term $q=2$
realizes exactly $a$ carries while every term has at least $a$; generalizes
Theorems~\ref{thm:pdvd} and \ref{thm:psq}.
\end{conjecture}

\section{Algorithms}

\textbf{Direct evaluation.} Iterated pairwise gcd of
$\{\bin{qk}{k} : 2 \le q \le k+1\}$, short-circuiting at $1$; $O(k)$ terms.

\textbf{Kummer carry valuation.} Compute $\val_p(\bin{qk}{k})$ by counting
base-$p$ carries adding $k$ and $(q-1)k$, never forming the huge coefficient;
$O(\log_p(qk))$ per term.

\textbf{Corrected closed form.} For each prime $p \mid n$, compute
$a = \val_p(n)$, $m = n/p^a$, exponent $\max(0, a - \lfloor\log_p m\rfloor)$;
return the maximum prime power.

\section{Discussion and conclusion}

The same Kummer carry count that controls a single $\bin{a}{b}$ controls the
entire gcd through the minimum \eqref{eq:min}. Stephan's formula was the $m = 1$
specialization of the correct law, exact precisely where no complementary factor
exists; its failure localized its own correction, of magnitude
$\lfloor\log_p m\rfloor$ digits. The disproof and prime-fibre exactness are
machine-checked, so Theorems~\ref{thm:disproof}, \ref{thm:pdvd}, and
\ref{thm:psq} are facts. What looked like a formula about prime powers was, all
along, a formula about carries.

