function BASE_P_CARRIES(a, b, p):
    carries <- 0; carry <- 0
    while a > 0 or b > 0 or carry > 0:
        s <- (a mod p) + (b mod p) + carry
        carry <- 1 if s >= p else 0
        carries <- carries + carry
        a <- a div p; b <- b div p
    return carries

function VP_BINOM(k, q, p):
    return BASE_P_CARRIES(k, (q-1)*k, p)   # = v_p(C(q*k, k))

