def base_p_carries(a: int, b: int, p: int) -> int:
    """Carries when adding a and b in base p (Kummer's theorem)."""
    carries = carry = 0
    while a > 0 or b > 0 or carry > 0:
        s = (a % p) + (b % p) + carry
        carry = 1 if s >= p else 0
        carries += carry
        a //= p
        b //= p
    return carries

def kummer_valuation(k: int, q: int, p: int) -> int:
    """v_p( C(q*k, k) ) = carries adding k and (q-1)*k in base p."""
    return base_p_carries(k, (q - 1) * k, p)

from typing import Dict

def factorize(n: int) -> Dict[int, int]:
    factors: Dict[int, int] = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        factors[n] = factors.get(n, 0) + 1
    return factors

def ilog(p: int, m: int) -> int:
    if m < 1:
        return 0
    e = 0
    while p ** (e + 1) <= m:
        e += 1
    return e

def corrected_formula(k: int) -> int:
    n = k + 1
    best = 1
    for p, a in factorize(n).items():
        m = n // (p ** a)
        best = max(best, p ** max(0, a - ilog(p, m)))
    return best
